/// Static (unfocused) look of a sidebar text field: a quiet rounded box
/// with placeholder or value text. Focus swaps in the live editor.
fn input_box(text: &str, placeholder: bool) -> Div {
    div()
        .px(px(8.))
        .py(px(5.))
        .rounded(px(5.))
        .bg(rgb(bg_well()))
        .border_1()
        .border_color(border_control())
        .text_size(px(12.))
        .truncate()
        .text_color(rgb(if placeholder {
            TEXT_DIM
        } else {
            TEXT_SECONDARY
        }))
        .child(text.to_string())
}

/// Gradient placeholder seed from the content hash until the thumbnail loads.
fn placeholder_tint(hash: &str) -> (u32, u32) {
    let b = hash.as_bytes();
    let i = b.first().copied().unwrap_or(0) as usize + b.get(1).copied().unwrap_or(0) as usize;
    FILM[i % FILM.len()]
}

fn as_photo(p: &DbPhoto) -> Photo {
    Photo {
        id: p.id,
        filename: p.filename.clone(),
        rating: p.rating,
        picked: p.picked,
        rejected: p.rejected,
        sync: p.sync,
        tint: (0, 0),
    }
}

/// GPUI uploads `RenderImage` buffers as BGRA even though its public frame
/// type is backed by `image::RgbaImage`. JPEG decoders produce RGBA, so swap
/// red and blue before handing the bytes to GPUI.
fn rgba_to_bgra_in_place(bytes: &mut [u8]) {
    for pixel in bytes.chunks_exact_mut(4) {
        pixel.swap(0, 2);
    }
}

fn render_image_from_jpeg(jpeg: &[u8]) -> Option<Arc<RenderImage>> {
    let rgba = image::load_from_memory(jpeg).ok()?.to_rgba8();
    let (w, h) = (rgba.width(), rgba.height());
    let mut pixels = rgba.into_raw();
    rgba_to_bgra_in_place(&mut pixels);
    let buf = image::RgbaImage::from_raw(w, h, pixels)?;
    Some(Arc::new(RenderImage::new(smallvec::smallvec![
        image::Frame::new(buf)
    ])))
}

