/// V12: a metadata change set. Field commits pass Some (empty clears on
/// single, no-ops on batch); preset apply passes None for empty fields.
#[derive(Clone, Debug, Default)]
struct MetaPatch {
    title: Option<String>,
    caption: Option<String>,
    headline: Option<String>,
    creator: Option<String>,
    copyright: Option<String>,
    rights: Option<String>,
    contact: Option<String>,
    location: Option<String>,
    keywords_add: Vec<String>,
    keywords_remove: Vec<String>,
    keywords_replace: Option<Vec<String>>,
}

impl MetaPatch {
    fn is_empty(&self) -> bool {
        self.title.is_none()
            && self.caption.is_none()
            && self.headline.is_none()
            && self.creator.is_none()
            && self.copyright.is_none()
            && self.rights.is_none()
            && self.contact.is_none()
            && self.location.is_none()
            && self.keywords_add.is_empty()
            && self.keywords_remove.is_empty()
            && self.keywords_replace.is_none()
    }

    /// Compute the after-values, or None when nothing would change.
    /// Batch mode never clears text fields (empty commit = untouched).
    fn apply_to(
        &self,
        meta: &laika_core::catalog::PhotoMeta,
        kws: &[String],
        batch: bool,
    ) -> Option<(laika_core::catalog::PhotoMeta, Vec<String>)> {
        let mut m = meta.clone();
        let mut changed = false;
        let mut set = |slot: &mut String, v: &Option<String>| {
            if let Some(v) = v {
                if batch && v.is_empty() {
                    return;
                }
                if *slot != *v {
                    *slot = v.clone();
                    changed = true;
                }
            }
        };
        set(&mut m.title, &self.title);
        set(&mut m.caption, &self.caption);
        set(&mut m.headline, &self.headline);
        set(&mut m.creator, &self.creator);
        set(&mut m.copyright, &self.copyright);
        set(&mut m.rights, &self.rights);
        set(&mut m.contact, &self.contact);
        set(&mut m.location, &self.location);
        let mut nk = kws.to_vec();
        if let Some(rep) = &self.keywords_replace {
            if &nk != rep {
                nk = rep.clone();
                changed = true;
            }
        } else {
            for k in &self.keywords_add {
                if !nk.contains(k) {
                    nk.push(k.clone());
                    changed = true;
                }
            }
            let before = nk.len();
            nk.retain(|k| !self.keywords_remove.contains(k));
            changed |= nk.len() != before;
        }
        changed.then_some((m, nk))
    }
}

