/// V28: watermark numeric steppers (ids double as element tags).
#[derive(Clone, Copy)]
enum WmStep {
    FontSize = 0,
    Opacity = 1,
    Scale = 2,
}

impl WmStep {
    fn bump(self, wm: &mut WatermarkSpec, dir: i32) {
        match self {
            WmStep::FontSize => wm.font_pct = (wm.font_pct as i32 + dir).clamp(1, 20) as u32,
            WmStep::Opacity => wm.opacity = (wm.opacity as i32 + dir * 5).clamp(0, 100) as u8,
            WmStep::Scale => wm.scale_pct = (wm.scale_pct as i32 + dir * 5).clamp(1, 50) as u32,
        }
    }
}

