/// U10: existing-file policy — never silently overwrite.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Default, serde::Serialize, serde::Deserialize)]
enum ExportCollision {
    /// `name-2.jpg`, `name-3.jpg`, … (default).
    #[default]
    Suffix,
    /// Leave the existing file, count as skipped.
    Skip,
    /// Replace explicitly.
    Overwrite,
}

impl ExportCollision {
    fn label(self) -> &'static str {
        match self {
            ExportCollision::Suffix => "Suffix",
            ExportCollision::Skip => "Skip",
            ExportCollision::Overwrite => "Overwrite",
        }
    }

    fn parse(s: &str) -> Self {
        match s {
            "Skip" => ExportCollision::Skip,
            "Overwrite" => ExportCollision::Overwrite,
            _ => ExportCollision::Suffix,
        }
    }
}

