/// U10: cancellable background export run (sequential full renders).
#[derive(Debug)]
struct ExportRun {
    total: usize,
    done: usize,
    /// V09: files rendered from smart previews (offline originals).
    smart: usize,
    current: String,
    cancel: std::sync::Arc<std::sync::atomic::AtomicBool>,
    failed: Vec<(String, String)>,
}

/// U10: a run is finished when every file was attempted or it was
/// cancelled (cancelled runs accept retries and fresh starts).
fn run_finished(r: &ExportRun) -> bool {
    r.done >= r.total || r.cancel.load(std::sync::atomic::Ordering::Relaxed)
}

