/// U10: render geometry back to edit space (degrees) for sidecars.
fn geom_to_edit(g: &laika_develop::CropRender) -> edit::CropGeom {
    edit::CropGeom {
        rect: g.rect,
        angle: g.angle_rad.to_degrees(),
        flip_h: g.flip_h,
        flip_v: g.flip_v,
        rotation: g.rotation,
        upright: Default::default(),
    }
}

