fn import_stamp() -> String {
    std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .map(|d| d.as_secs().to_string())
        .unwrap_or_default()
}

/// Snapshot the files the import job should receive. Filtering here means
/// new-only card imports never copy/decode files already shown as imported.
fn selected_import_entries(
    entries: &[laika_core::import::ScanEntry],
    only_new: bool,
) -> Vec<laika_core::import::ScanEntry> {
    entries
        .iter()
        .filter(|entry| !only_new || !entry.previously_imported)
        .cloned()
        .collect()
}

/// Human volume sizes for the source picker.
fn fmt_bytes(bytes: u64) -> String {
    const GB: f64 = 1024. * 1024. * 1024.;
    const MB: f64 = 1024. * 1024.;
    let b = bytes as f64;
    if b >= GB {
        format!("{:.1} GB", b / GB)
    } else if b >= MB {
        format!("{:.0} MB", b / MB)
    } else {
        format!("{} KB", bytes / 1024.max(1))
    }
}

