/// Grading wheel index (0 shadows, 1 midtones, 2 highlights, 3 global):
/// its hue/sat/lum params start at `49 + 3 * wheel`.
const GRADE_WHEELS: [&str; 4] = ["Shadows", "Midtones", "Highlights", "Global"];

fn grade_base(wheel: usize) -> usize {
    edit::GRADING_RANGE.start + 3 * wheel
}

/// Hue/saturation disc for the grading wheels (BGRA for GPUI): hue runs
/// counter-clockwise from red at 3 o'clock, saturation grows outward.
fn grading_wheel_image() -> Arc<RenderImage> {
    const N: u32 = 256;
    let mut px = vec![0u8; (N * N * 4) as usize];
    let c = (N as f32 - 1.) / 2.;
    for y in 0..N {
        for x in 0..N {
            let (dx, dy) = ((x as f32 - c) / c, (y as f32 - c) / c);
            let r = (dx * dx + dy * dy).sqrt();
            let alpha = ((1. - r) * c).clamp(0., 1.);
            if alpha <= 0. {
                continue;
            }
            let hue = (-dy).atan2(dx).to_degrees().rem_euclid(360.);
            let sat = r.min(1.) * 0.85;
            let hh = hue / 60.;
            let f = hh - hh.floor();
            let (p, q, t) = (1. - sat, 1. - sat * f, 1. - sat * (1. - f));
            let (rr, gg, bb) = match hh.floor() as i32 % 6 {
                0 => (1., t, p),
                1 => (q, 1., p),
                2 => (p, 1., t),
                3 => (p, q, 1.),
                4 => (t, p, 1.),
                _ => (1., p, q),
            };
            // Dimmed so the white marker reads on top; premultiplied edge.
            let v = 0.62 * alpha;
            let i = ((y * N + x) * 4) as usize;
            px[i] = (bb * v * 255.) as u8;
            px[i + 1] = (gg * v * 255.) as u8;
            px[i + 2] = (rr * v * 255.) as u8;
            px[i + 3] = (alpha * 255.) as u8;
        }
    }
    let buf = image::RgbaImage::from_raw(N, N, px).expect("wheel dims");
    Arc::new(RenderImage::new(smallvec::smallvec![image::Frame::new(
        buf
    )]))
}

impl Panel {
    fn label(self) -> &'static str {
        match self {
            Panel::Curve => "Tone Curve",
            Panel::Hsl => "Color Mix",
            Panel::Detail => "Detail",
            Panel::Optics => "Optics",
            Panel::Effects => "Effects",
            Panel::Grading => "Color Grading",
            Panel::Transform => "Transform",
        }
    }

    /// Param indices the panel shows and resets.
    fn indices(self) -> Vec<usize> {
        match self {
            Panel::Curve => edit::CURVE_RANGE.collect(),
            Panel::Hsl => edit::HSL_RANGE.collect(),
            Panel::Detail => edit::DETAIL_RANGE.collect(),
            Panel::Optics => edit::OPTICS_RANGE.collect(),
            Panel::Effects => edit::EFFECTS_PARAMS.to_vec(),
            Panel::Grading => edit::GRADING_RANGE.collect(),
            Panel::Transform => edit::TRANSFORM_RANGE.collect(),
        }
    }

    /// Whether the panel has a persisted bypass flag (geometry has none).
    fn bypassable(self) -> bool {
        self != Panel::Transform
    }

    fn flag(self, e: &edit::Edit) -> bool {
        match self {
            Panel::Curve => e.curve_on,
            Panel::Hsl => e.hsl_on,
            Panel::Detail => e.detail_on,
            Panel::Optics => e.optics_on,
            Panel::Effects => e.effects_on,
            Panel::Grading => e.grading_on,
            Panel::Transform => true,
        }
    }
}

