    /// U12: saved filter sets — apply on click, × deletes, Enter in the
    /// name box saves the current set.
    fn preset_section(&self, window: &mut Window, cx: &mut Context<Self>) -> Div {
        let _p = crate::ProfSpan("preset_section", Instant::now());
        let presets = self
            .catalog
            .as_ref()
            .map(|c| c.list_filter_presets())
            .unwrap_or_default();
        let mut col = div()
            .flex()
            .flex_col()
            .gap(px(1.))
            .child(section_header::section_header(
                "Filter presets",
                false,
                window,
            ));
        for (pi, (name, _)) in presets.iter().enumerate() {
            let label = name.clone();
            let del = name.clone();
            col = col.child(
                div()
                    .flex()
                    .items_center()
                    .gap(px(4.))
                    .px(px(6.))
                    .child(
                        div()
                            .flex_1()
                            .id(("preset", pi))
                            .on_hover(self.tip("Apply this filter set"))
                            .on_click(cx.listener(move |this, _, _, cx| {
                                this.apply_filter_preset(&label, cx);
                            }))
                            .child(list_row::list_row(name, "", 0x424446, false)),
                    )
                    .child(
                        div()
                            .id(("preset-del", pi))
                            .px(px(6.))
                            .font_family(SANS)
                            .text_size(px(10.5))
                            .text_color(rgb(TEXT_DIMMER))
                            .hover(|s| s.text_color(rgb(0xE56060)))
                            .on_hover(self.tip("Delete this preset"))
                            .on_click(cx.listener(move |this, _, _, cx| {
                                if let Some(cat) = this.catalog.as_ref() {
                                    cat.delete_filter_preset(&del);
                                }
                                cx.notify();
                            }))
                            .child("×".to_string()),
                    ),
            );
        }
        col.child(div().px(px(14.)).pt(px(4.)).child(self.field_cell(
            text_input::FieldId::FilterPresetName,
            input_box("Save current filters…", true),
            false,
            "Type a name, Enter saves the current filters",
            cx,
        )))
    }

    /// U12: camera/lens browser rows with counts (top values) plus the
    /// capture-date window (always available, even without EXIF).
    fn metadata_browser(&self, window: &mut Window, cx: &mut Context<Self>) -> Div {
        let _p = crate::ProfSpan("metadata_browser", Instant::now());
        let (cameras, lenses) = {
            let rev = self.photos_rev.get() ^ ((self.photos.len() as u64) << 32);
            let cached = {
                let memo = self.meta_lists_memo.borrow();
                (memo.0 == rev).then(|| memo.1.clone())
            };
            match cached {
                Some(lists) => lists,
                None => {
                    let lists = self
                        .catalog
                        .as_ref()
                        .map(|c| (c.distinct_cameras(), c.distinct_lenses()))
                        .unwrap_or_default();
                    *self.meta_lists_memo.borrow_mut() = (rev, lists.clone());
                    lists
                }
            }
        };
        let mut col = div()
            .flex()
            .flex_col()
            .gap(px(1.))
            .child(section_header::section_header(
                "Camera & lens",
                false,
                window,
            ));
        for (ci, (name, count)) in cameras.iter().enumerate() {
            let label = name.clone();
            let active = self.state.filters.camera.as_deref() == Some(name.as_str());
            col = col.child(
                div()
                    .px(px(6.))
                    .id(("camera", ci))
                    .on_hover(self.tip("Filter to this camera"))
                    .on_click(cx.listener(move |this, _, _, cx| {
                        let f = &mut this.state.filters;
                        if f.camera.as_deref() == Some(label.as_str()) {
                            f.camera = None;
                        } else {
                            f.camera = Some(label.clone());
                        }
                        cx.notify();
                    }))
                    .child(list_row::list_row(
                        // EXIF ASCII values arrive quoted ("NIKON D600").
                        name.trim_matches('"'),
                        &count.to_string(),
                        if active { accent_line() } else { 0x424446 },
                        active,
                    )),
            );
        }
        for (li, (name, count)) in lenses.iter().enumerate() {
            let label = name.clone();
            let active = self.state.filters.lens.as_deref() == Some(name.as_str());
            col = col.child(
                div()
                    .px(px(6.))
                    .id(("lens", li))
                    .on_hover(self.tip("Filter to this lens"))
                    .on_click(cx.listener(move |this, _, _, cx| {
                        let f = &mut this.state.filters;
                        if f.lens.as_deref() == Some(label.as_str()) {
                            f.lens = None;
                        } else {
                            f.lens = Some(label.clone());
                        }
                        cx.notify();
                    }))
                    .child(list_row::list_row(
                        // EXIF ASCII values arrive quoted ("NIKON D600").
                        name.trim_matches('"'),
                        &count.to_string(),
                        if active { accent_line() } else { 0x424446 },
                        active,
                    )),
            );
        }
        // U12: capture-date window edges (empty clears).
        let date = |id: text_input::FieldId,
                    hint: &'static str,
                    tip: &'static str,
                    value: Option<String>,
                    cx: &mut Context<Self>| {
            let value = value.unwrap_or_default();
            div().flex_1().min_w_0().child(self.field_cell(
                id,
                input_box(
                    if value.is_empty() {
                        hint
                    } else {
                        value.as_str()
                    },
                    value.is_empty(),
                ),
                false,
                tip,
                cx,
            ))
        };
        col = col
            .child(
                div()
                    .px(px(14.))
                    .pt(px(10.))
                    .pb(px(4.))
                    .text_size(px(11.))
                    .text_color(rgb(TEXT_DIM))
                    .child("Capture date"),
            )
            .child(
                div()
                    .flex()
                    .items_center()
                    .gap(px(6.))
                    .px(px(14.))
                    .child(date(
                        text_input::FieldId::DateFrom,
                        "From",
                        "Filter from this capture date (YYYY-MM-DD)",
                        self.state.filters.date_from.clone(),
                        cx,
                    ))
                    .child(date(
                        text_input::FieldId::DateTo,
                        "To",
                        "Filter up to this capture date (YYYY-MM-DD)",
                        self.state.filters.date_to.clone(),
                        cx,
                    )),
            );
        col
    }

    /// U12: apply a saved filter set (unknown fields fall back to neutral).
    fn apply_filter_preset(&mut self, name: &str, cx: &mut Context<Self>) {
        let json = self
            .catalog
            .as_ref()
            .map(|c| {
                c.list_filter_presets()
                    .into_iter()
                    .find(|(n, _)| n == name)
                    .map(|(_, j)| j)
            })
            .flatten();
        match json.and_then(|j| serde_json::from_str::<laika_core::state::Filters>(&j).ok()) {
            Some(f) => {
                self.state.filters = f;
                self.status_note = format!("filter “{name}” applied");
            }
            None => {
                self.status_note = format!("filter “{name}” is unreadable — kept current");
            }
        }
        cx.notify();
    }

    fn sync_footer(&self, _window: &mut Window, cx: &mut Context<Self>) -> Div {
        let _p = crate::ProfSpan("sync_footer", Instant::now());
        // U05/V01: live throughput + ETA while importing, with Cancel.
        let (title, frac, caption) = match &self.import {
            Some(p) => {
                let processing = p.transferred >= p.total;
                let moved = if p.mode_label == "copy" {
                    p.copy_bytes.load(Ordering::Relaxed)
                } else {
                    p.bytes
                };
                let secs = p.started.elapsed().as_secs_f32().max(0.1);
                let mb_s = moved as f32 / 1024. / 1024. / secs;
                let eta = if mb_s > 0.05 && p.bytes_total > moved {
                    let left = (p.bytes_total - moved) as f32 / 1024. / 1024. / mb_s;
                    if left < 60. {
                        format!(" · ~{left:.0}s left")
                    } else {
                        format!(" · ~{:.0} min left", left / 60.)
                    }
                } else {
                    String::new()
                };
                if processing {
                    (
                        "Importing".to_string(),
                        p.done as f32 / p.total.max(1) as f32,
                        format!("{} / {} · {}", p.done, p.total, p.current),
                    )
                } else {
                    (
                        "Transferring".to_string(),
                        p.transferred as f32 / p.total.max(1) as f32,
                        format!(
                            "{} / {} · {} · {:.1} MB/s{eta}",
                            p.transferred, p.total, p.current, mb_s
                        ),
                    )
                }
            }
            None => self.sync_status(),
        };
        let (queued, failed) = self.queue_depth();
        div()
            .border_t_1()
            .border_color(hairline())
            .p(px(14.))
            .flex()
            .flex_col()
            .gap(px(9.))
            // App status line (acknowledgements, errors) above the backup
            // state, so neither overwrites the other.
            .when(!self.status_note.is_empty(), |d| {
                d.child(
                    div()
                        .pb(px(6.))
                        .mb(px(2.))
                        .border_b_1()
                        .border_color(hairline())
                        .text_size(px(11.))
                        .line_height(relative(1.35))
                        .text_color(rgb(TEXT_SECONDARY))
                        .child(self.status_note.clone()),
                )
            })
            .child(
                div()
                    .flex()
                    .items_baseline()
                    .justify_between()
                    .gap(px(8.))
                    .child(
                        div()
                            .text_size(px(12.))
                            .font_weight(FontWeight::SEMIBOLD)
                            .text_color(rgb(TEXT_SECONDARY))
                            .child(title),
                    )
                    .child(
                        div()
                            .min_w_0()
                            .truncate()
                            .text_size(px(11.))
                            .text_color(rgb(TEXT_DIM))
                            .child(caption.clone()),
                    ),
            )
            .child(
                div()
                    .h(px(3.))
                    .rounded(px(2.))
                    .bg(rgb(track()))
                    .when(
                        self.import.is_none() && !self.sync_settings.configured(),
                        |d| d.h(px(0.)).overflow_hidden(),
                    )
                    .child(
                        div()
                            .h(px(3.))
                            .w(relative(frac))
                            .rounded(px(2.))
                            .bg(rgb(progress_fill())),
                    ),
            )
            // U05: cancel a running import; reopen review/detail dialog.
            .when(self.import.is_some(), |d| {
                d.child(
                    div().flex().gap(px(6.)).children([
                        div()
                            .id("import-cancel")
                            .px(px(8.))
                            .py(px(4.))
                            .rounded(px(3.))
                            .border_1()
                            .border_color(border_control())
                            .font_family(SANS)
                            .text_size(px(10.))
                            .text_color(rgb(0xE56060))
                            .hover(|s| s.bg(rgb(bg_row_hover())))
                            .on_click(cx.listener(|this, _, _, cx| this.cancel_import(cx)))
                            .child("Cancel"),
                        div()
                            .id("import-details")
                            .px(px(8.))
                            .py(px(4.))
                            .rounded(px(3.))
                            .border_1()
                            .border_color(border_control())
                            .font_family(SANS)
                            .text_size(px(10.))
                            .text_color(rgb(TEXT_SECONDARY))
                            .hover(|s| s.bg(rgb(bg_row_hover())))
                            .on_click(cx.listener(|this, _, _, cx| {
                                this.import_open = true;
                                cx.notify();
                            }))
                            .child("Details"),
                    ]),
                )
            })
            .when(self.import.is_none(), |d| {
                d.child(
                    div().flex().flex_wrap().gap(px(6.)).children([
                        div()
                            .id("sync-now")
                            .px(px(8.))
                            .py(px(4.))
                            .rounded(px(3.))
                            .border_1()
                            .border_color(border_control())
                            .font_family(SANS)
                            .text_size(px(10.))
                            .text_color(rgb(TEXT_SECONDARY))
                            .hover(|s| s.bg(rgb(bg_row_hover())))
                            .on_click(cx.listener(|this, _, _, cx| this.start_sync(cx)))
                            .child("Sync now"),
                        div()
                            .id("sync-retry")
                            .px(px(8.))
                            .py(px(4.))
                            .rounded(px(3.))
                            .border_1()
                            .border_color(border_control())
                            .font_family(SANS)
                            .text_size(px(10.))
                            .text_color(rgb(if failed > 0 { 0xE56060 } else { TEXT_DIM }))
                            .hover(|s| s.bg(rgb(bg_row_hover())))
                            .on_click(cx.listener(|this, _, _, cx| this.retry_failed_sync(cx)))
                            .when(failed == 0, |d| d.hidden())
                            .child(format!("Retry {failed}")),
                        div()
                            .id("sync-settings")
                            .px(px(8.))
                            .py(px(4.))
                            .rounded(px(3.))
                            .border_1()
                            .border_color(border_control())
                            .font_family(SANS)
                            .text_size(px(10.))
                            .text_color(rgb(TEXT_SECONDARY))
                            .hover(|s| s.bg(rgb(bg_row_hover())))
                            .on_click(cx.listener(|this, _, _, cx| {
                                if this.sync_open {
                                    this.close_modals(cx);
                                } else {
                                    this.open_sync(cx);
                                }
                            }))
                            .child("Settings"),
                    ]),
                )
            })
            .when(queued + failed == 0 && self.import.is_none(), |d| d)
            .child(self.apple_footer(cx))
    }

    /// Real footer state: progress from queue depth + throughput, never fake.
    fn sync_status(&self) -> (String, f32, String) {
        if !self.sync_settings.configured() {
            return ("Backup".to_string(), 0., "Not configured".to_string());
        }
        let (queued, failed) = self.queue_depth();
        let total_photos = self.photos.len().max(1);
        let synced = self
            .photos
            .iter()
            .filter(|p| matches!(p.sync, SyncState::Synced))
            .count();
        let frac = synced as f32 / total_photos as f32;
        if !self.sync_last_error.is_empty() {
            return (
                "Backup".to_string(),
                frac,
                format!("error: {}", self.sync_last_error),
            );
        }
        if queued + self.sync_inflight > 0 {
            let mb = self.sync_throughput();
            let cur = if self.sync_current.is_empty() {
                "".to_string()
            } else {
                format!(" · {}", self.sync_current)
            };
            let rate = if mb > 0.05 {
                format!(" · {mb:.1} MB/s")
            } else {
                String::new()
            };
            return (
                "Backup".to_string(),
                frac,
                format!(
                    "{} left · {failed} failed{cur}{rate}",
                    queued + self.sync_inflight
                ),
            );
        }
        if failed > 0 {
            return (
                "Backup".to_string(),
                frac,
                format!("{failed} failed — Retry failed to resume"),
            );
        }
        match self.sync_last_ok {
            Some(t) => (
                "Backup".to_string(),
                1.,
                format!("all synced · {}", Self::relative_time(t)),
            ),
            None => (
                "Backup".to_string(),
                frac,
                format!("{synced}/{total_photos} synced"),
            ),
        }
    }

