    fn filter_chip(
        &self,
        label: &'static str,
        active: bool,
        id: usize,
        cx: &mut Context<Self>,
    ) -> impl IntoElement + use<> {
        use laika_core::state::{FileType, FlagFilter};
        // U04: hover tips name each filter's scope.
        let tip = match id {
            0 => "Show photos rated 3 stars and up",
            1 => "Show picked photos only (P)",
            2 => "Show rejected photos only (X)",
            3 => "Show RAW files only",
            4 => "Show raster photos (JPEG and friends)",
            5 => "Show photos still uploading or failed",
            7 => "Show photos whose originals are missing",
            8 => "Show photos with no star rating yet (cull the undecided)",
            9 => "Show photos that are neither picked nor rejected",
            _ => "Clear every filter, search, and scope",
        };
        div()
            .id(("filter", id))
            .on_hover(self.tip(tip))
            .on_click(cx.listener(move |this, _, _, cx| {
                let f = &mut this.state.filters;
                match id {
                    0 => {
                        f.min_stars = if f.min_stars >= 3 { 0 } else { 3 };
                    }
                    1 => {
                        f.flag = if f.flag == FlagFilter::Picked {
                            FlagFilter::All
                        } else {
                            FlagFilter::Picked
                        };
                    }
                    2 => {
                        f.flag = if f.flag == FlagFilter::Rejected {
                            FlagFilter::All
                        } else {
                            FlagFilter::Rejected
                        };
                    }
                    3 => {
                        f.file_type = if f.file_type == FileType::Raw {
                            FileType::All
                        } else {
                            FileType::Raw
                        };
                    }
                    4 => {
                        f.file_type = if f.file_type == FileType::Raster {
                            FileType::All
                        } else {
                            FileType::Raster
                        };
                    }
                    5 => f.unsynced_only = !f.unsynced_only,
                    7 => f.missing_only = !f.missing_only,
                    8 => f.unrated_only = !f.unrated_only,
                    9 => {
                        f.flag = if f.flag == FlagFilter::Unflagged {
                            FlagFilter::All
                        } else {
                            FlagFilter::Unflagged
                        };
                    }
                    // U12: clear-all resets filters, search, and scope.
                    _ => {
                        this.state.filters = Default::default();
                    }
                }
                // A hidden primary stays put; stepping enters the visible set.
                cx.notify();
            }))
            .child(chip::filter_chip(label, active))
    }

    /// U06: auto-advance toggle — rating/flag keys step to the next visible
    /// photo while culling. Same control as the `A` shortcut.
    fn advance_toggle(&self, cx: &mut Context<Self>) -> impl IntoElement + use<> {
        let on = self.auto_advance;
        div()
            .id("advance-toggle")
            .on_hover(self.tip("Auto-advance after rating/flag (A)"))
            .on_click(cx.listener(|this, _, _, cx| {
                this.auto_advance = !this.auto_advance;
                this.status_note = if this.auto_advance {
                    "auto-advance on — ratings step to the next photo".to_string()
                } else {
                    "auto-advance off".to_string()
                };
                cx.notify();
            }))
            .child(chip::filter_chip("Advance", on))
    }

