    fn paste_count(&self) -> usize {
        self.targets().len().max(1)
    }

    /// Apply the clipboard to every selected photo (writes sidecars).
    fn paste_settings(&mut self, cx: &mut Context<Self>) {
        let Some(cb) = self.state.clipboard else {
            self.status_note = "nothing copied yet".to_string();
            cx.notify();
            return;
        };
        let ids = self.targets();
        if ids.is_empty() {
            self.status_note = "no visible photos targeted".to_string();
            cx.notify();
            return;
        }
        // U14: one step per target, one undo unit for the batch.
        let befores: Vec<(i64, edit::Snap)> = ids
            .iter()
            .map(|pid| (*pid, self.snap_current(*pid)))
            .collect();
        for pid in &ids {
            // V22: Transform sliders are geometry — like crops, they
            // never paste onto other frames.
            let e = self.state.edit(*pid);
            let keep = e.params;
            e.params = cb;
            e.params[edit::TRANSFORM_RANGE].copy_from_slice(&keep[edit::TRANSFORM_RANGE]);
        }
        for (pid, before) in &befores {
            self.record_step(*pid, "Paste settings", "", before.clone());
        }
        // U14: undoing the paste restores every target at once.
        self.last_batch = ids.clone();
        self.last_was_meta = false;
        self.last_was_remove = false;
        self.redo_batch.clear();
        if let Some(pid) = self.state.primary {
            if ids.contains(&pid) {
                self.values = self.state.edit(pid).params;
            }
        }
        self.edits_dirty = true;
        // U02: every target acknowledges to the DB; failures shelve for
        // retry instead of vanishing.
        let mut failed = 0;
        for pid in &ids {
            if !self.persist_photo(*pid) {
                failed += 1;
            }
            // Grid/Loupe thumbnails re-render with the pasted look.
            self.sync_derived(*pid, cx);
        }
        for pid in &ids {
            if let Some(photo) = self.photos.iter().find(|p| p.id == *pid).cloned() {
                let hist: Vec<String> = self
                    .state
                    .edits
                    .get(pid)
                    .map(|e| {
                        e.history
                            .iter()
                            .rev()
                            .take(8)
                            .map(|s| {
                                if s.value.is_empty() {
                                    s.label.clone()
                                } else {
                                    format!("{} {}", s.label, s.value)
                                }
                            })
                            .collect()
                    })
                    .unwrap_or_default();
                // V12: full descriptive block (title/caption/included keywords).
                let auth = self
                    .catalog
                    .as_ref()
                    .map(|cat| cat.photo_authorship(*pid))
                    .unwrap_or_default();
                let geom = self.sidecar_geom(*pid);
                match laika_core::xmp::write(
                    &photo.path,
                    &cb,
                    photo.rating,
                    &hist,
                    None,
                    &auth,
                    &geom,
                ) {
                    Ok(()) => {
                        if let Some(cat) = self.catalog.as_ref() {
                            if let Err(e) = cat.remember_sidecar_write(
                                *pid,
                                laika_core::xmp::sidecar_mtime(&photo.path).unwrap_or(0),
                            ) {
                                self.save_error = Some(e);
                                failed += 1;
                            } else {
                                cat.enqueue(*pid, "sidecar");
                            }
                        }
                    }
                    Err(e) => {
                        self.save_error = Some(e);
                        failed += 1;
                        // Every failed target retries, not just the first.
                        self.sidecar_pending.insert(*pid);
                        self.sidecar_deadline = None;
                    }
                }
            }
        }
        self.submit_dev(cx);
        self.sync_staged = true;
        if failed > 0 {
            self.status_note = self
                .save_error
                .clone()
                .unwrap_or_else(|| format!("pasted with {failed} save failures — retry available"));
        } else {
            self.status_note = format!("pasted to {}", ids.len());
        }
        self.pump_sync(cx);
        cx.notify();
    }

