    /// V20: slideshow interval chips and on/off toggles for Settings.
    fn slideshow_settings(&self, cx: &mut Context<Self>) -> Div {
        let prefs = self.slides.prefs;
        let mut intervals = div().flex().flex_wrap().gap(px(6.));
        for secs in laika_core::slideshow::INTERVALS {
            intervals = intervals.child(
                div()
                    .id(("slide-interval-pref", secs as usize))
                    .on_click(cx.listener(move |this, _, _, cx| {
                        let mut p = this.slides.prefs;
                        p.interval_secs = secs;
                        this.set_slide_prefs(p, cx);
                    }))
                    .child(chip::filter_chip(
                        &format!("{secs}s"),
                        prefs.interval_secs == secs,
                    )),
            );
        }
        let flag = |id: &'static str, label: &'static str, on: bool| {
            div().id(id).child(chip::filter_chip(label, on))
        };
        div()
            .flex()
            .flex_col()
            .gap(px(8.))
            .child(
                div()
                    .flex()
                    .items_center()
                    .gap(px(8.))
                    .child(
                        div()
                            .w(px(120.))
                            .flex_none()
                            .text_size(px(12.))
                            .text_color(rgb(TEXT_DIM))
                            .child("Interval"),
                    )
                    .child(intervals),
            )
            .child(
                div()
                    .flex()
                    .items_center()
                    .gap(px(8.))
                    .child(
                        div()
                            .w(px(120.))
                            .flex_none()
                            .text_size(px(12.))
                            .text_color(rgb(TEXT_DIM))
                            .child("Playback"),
                    )
                    .child(
                        flag("slide-pref-loop", "Loop", prefs.looped).on_click(cx.listener(
                            |this, _, _, cx| {
                                let mut p = this.slides.prefs;
                                p.looped = !p.looped;
                                this.set_slide_prefs(p, cx);
                            },
                        )),
                    )
                    .child(
                        flag("slide-pref-fade", "Fade", prefs.fade).on_click(cx.listener(
                            |this, _, _, cx| {
                                let mut p = this.slides.prefs;
                                p.fade = !p.fade;
                                this.set_slide_prefs(p, cx);
                            },
                        )),
                    )
                    .child(
                        flag("slide-pref-caption", "Caption from title", prefs.caption).on_click(
                            cx.listener(|this, _, _, cx| {
                                let mut p = this.slides.prefs;
                                p.caption = !p.caption;
                                this.set_slide_prefs(p, cx);
                            }),
                        ),
                    ),
            )
    }

